//! Checkpoint 2, technique tests: is the library correct for the right
//! reasons?
//!
//! Run: cargo test --test technique
//!
//! These tests look at how the code works: how large the types are, what is
//! allocated, which trait method really runs, and how wide the arithmetic
//! is. All of them must pass, in debug and with `--release`, for the
//! "proficient" level in RUBRIC.md. Do not edit this file.

mod common;

use std::cell::Cell;
use std::mem::size_of;
use std::rc::Rc;

use common::measure;
use postage::carrier::{Carrier, Dash, Discounted, Region, Snail, Zone};
use postage::parcel::{Contents, Dimensions, Grams, Parcel, ParcelError};
use postage::quote::{cheapest, total};

const GOODS: Contents = Contents::Goods { fragile: false };
const NEAR: Zone = Zone::International(Region::Near);

fn parcel(grams: u32, sides: (u32, u32, u32), contents: Contents) -> Parcel {
    let dimensions = Dimensions::new(sides.0, sides.1, sides.2).expect("valid sides");
    Parcel::new(Grams::new(grams), dimensions, contents).expect("valid parcel")
}

fn small() -> Parcel {
    parcel(1500, (300, 200, 100), GOODS)
}

/// A carrier that counts how often each method is asked. Its `accepts` is
/// overridden: it answers without computing a price.
#[derive(Default)]
struct Counter {
    cents: Option<u32>,
    prices: Cell<u32>,
    accepts: Cell<u32>,
}

impl Counter {
    fn charging(cents: u32) -> Counter {
        Counter {
            cents: Some(cents),
            ..Counter::default()
        }
    }
}

impl Carrier for Counter {
    fn name(&self) -> &str {
        "Counter"
    }
    fn price(&self, _parcel: &Parcel, _zone: Zone) -> Option<u32> {
        self.prices.set(self.prices.get() + 1);
        self.cents
    }
    fn accepts(&self, _parcel: &Parcel, _zone: Zone) -> bool {
        self.accepts.set(self.accepts.get() + 1);
        self.cents.is_some()
    }
}

/// A carrier with the default `accepts`. It counts the price requests in a
/// counter that the test shares with it.
struct Plain {
    cents: Option<u32>,
    prices: Rc<Cell<u32>>,
}

impl Carrier for Plain {
    fn name(&self) -> &str {
        "Plain"
    }
    fn price(&self, _parcel: &Parcel, _zone: Zone) -> Option<u32> {
        self.prices.set(self.prices.get() + 1);
        self.cents
    }
}

fn ask<C: Carrier>(carrier: &C) -> bool {
    carrier.accepts(&small(), Zone::Local)
}

// ----------------------------------------------------------------- layout

#[test]
fn a_newtype_costs_nothing() {
    assert_eq!(
        size_of::<Grams>(),
        size_of::<u32>(),
        "Grams wraps one u32 and must be exactly as large as a u32"
    );
}

#[test]
fn value_types_are_small() {
    // Building a parcel first: the sizes mean something only for types
    // that work.
    let _ = small();
    assert!(
        size_of::<Dimensions>() <= 12,
        "Dimensions is {} bytes; three sides of at most 2000 mm need at most 12",
        size_of::<Dimensions>()
    );
    assert!(
        size_of::<Parcel>() <= 24,
        "Parcel is {} bytes; the budget is 24. Store the weight, the box and the contents, \
         and compute the billable weight and the size class when they are asked for.",
        size_of::<Parcel>()
    );
}

// ------------------------------------------------------------ wide numbers

#[test]
fn volume_of_the_largest_box_needs_64_bits() {
    let cube = Dimensions::new(2000, 2000, 2000).unwrap();
    assert_eq!(
        cube.volume_mm3(),
        8_000_000_000,
        "2000 * 2000 * 2000 does not fit in a u32; convert the sides before multiplying"
    );
    let heavy_air = Parcel::new(Grams::new(30_000), cube, GOODS).unwrap();
    assert_eq!(heavy_air.billable(), Grams::new(1_600_000));
}

#[test]
fn liquid_check_does_not_overflow() {
    let cube = Dimensions::new(2000, 2000, 2000).unwrap();
    let weight = Grams::new(30_000);
    // The cube holds exactly 8 000 000 ml.
    assert!(
        Parcel::new(
            weight,
            cube,
            Contents::Liquid {
                millilitres: 8_000_000
            }
        )
        .is_ok()
    );
    assert_eq!(
        Parcel::new(
            weight,
            cube,
            Contents::Liquid {
                millilitres: 8_000_001
            }
        ),
        Err(ParcelError::Liquid(8_000_001))
    );
    for millilitres in [u32::MAX, 4_294_968, 4_300_000, 3_000_000_000] {
        let small_box = Dimensions::new(10, 10, 10).unwrap();
        assert_eq!(
            Parcel::new(weight, small_box, Contents::Liquid { millilitres }),
            Err(ParcelError::Liquid(millilitres)),
            "{millilitres} ml are far more than one millilitre of box; \
             {millilitres} * 1000 must not be computed in a u32"
        );
    }
}

#[test]
fn discount_does_not_overflow() {
    struct Max;
    impl Carrier for Max {
        fn name(&self) -> &str {
            "Max"
        }
        fn price(&self, _parcel: &Parcel, _zone: Zone) -> Option<u32> {
            Some(u32::MAX)
        }
    }
    assert_eq!(
        Discounted::new(Max, 1)
            .unwrap()
            .price(&small(), Zone::Local),
        Some(4_252_017_623),
        "99 % of u32::MAX, rounded up; u32::MAX * 99 needs a wider type"
    );
    assert_eq!(
        Discounted::new(Max, 0)
            .unwrap()
            .price(&small(), Zone::Local),
        Some(u32::MAX)
    );
    assert_eq!(
        Discounted::new(Max, 100)
            .unwrap()
            .price(&small(), Zone::Local),
        Some(0)
    );
}

// -------------------------------------------------------------- allocation

#[test]
fn building_and_classifying_a_parcel_does_not_allocate() {
    let (class, heap) = measure(|| {
        let dimensions = Dimensions::new(100, 300, 200).unwrap();
        let p = Parcel::new(Grams::new(1500), dimensions, GOODS).unwrap();
        (p.size_class(), p.billable(), dimensions.volume_mm3())
    });
    assert_eq!(class.1, Grams::new(1500));
    assert_eq!(
        heap.calls, 0,
        "a parcel is a few numbers; building one and asking for its class allocated {} time(s)",
        heap.calls
    );
}

#[test]
fn pricing_does_not_allocate() {
    let dash = Dash::new("Dash", 300, 120);
    let cheap = Discounted::new(Snail, 10).unwrap();
    let p = small();
    let (prices, heap) = measure(|| {
        (
            Snail.price(&p, NEAR),
            dash.price(&p, NEAR),
            cheap.price(&p, NEAR),
            dash.name().len() + cheap.name().len(),
            dash.accepts(&p, NEAR),
        )
    });
    assert_eq!(prices, (Some(1400), Some(2700), Some(1260), 14, true));
    assert_eq!(
        heap.calls, 0,
        "asking for names and prices allocated {} time(s); `name` returns a borrowed &str and \
         a price is a number",
        heap.calls
    );
}

#[test]
fn comparing_carriers_does_not_allocate() {
    let carriers: Vec<Box<dyn Carrier>> = vec![
        Box::new(Snail),
        Box::new(Dash::new("Dash", 100, 50)),
        Box::new(Discounted::new(Snail, 30).unwrap()),
        Box::new(Dash::new("Other", 90, 60)),
    ];
    let parcels = [small(), small(), small()];
    let ((name, cents, sum), heap) = measure(|| {
        let quote = cheapest(&carriers, &parcels[0], Zone::Local).unwrap();
        (
            quote.carrier.name(),
            quote.cents,
            total(quote.carrier, &parcels, Zone::Local),
        )
    });
    assert_eq!((name, cents, sum), ("Dash", 200, Some(600)));
    assert_eq!(
        heap.calls, 0,
        "`cheapest` and `total` allocated {} time(s); the best quote so far fits in one \
         variable, a list of all quotes is not needed",
        heap.calls
    );
}

// ---------------------------------------------------------------- identity

#[test]
fn a_quote_borrows_the_winning_carrier() {
    let carriers: Vec<Box<dyn Carrier>> = vec![
        Box::new(Dash::new("same name", 100, 500)),
        Box::new(Dash::new("same name", 100, 50)),
        Box::new(Dash::new("same name", 100, 50)),
    ];
    let quote = cheapest(&carriers, &small(), Zone::Local).unwrap();
    assert_eq!(quote.cents, 200);
    // Two addresses are right. `carrier.as_ref()` borrows the carrier inside
    // the box. A plain `carrier` borrows the box in the slice, which is a
    // carrier too (SPEC section 4). Both belong to index 1 of the slice.
    let winner: *const dyn Carrier = quote.carrier;
    let inside_the_box: *const dyn Carrier = carriers[1].as_ref();
    let the_box: *const Box<dyn Carrier> = &carriers[1];
    assert!(
        std::ptr::addr_eq(winner, inside_the_box) || std::ptr::addr_eq(winner, the_box),
        "the quote must refer to the carrier at index 1 of the slice itself: the first of the \
         two cheapest, and not a copy of it"
    );
}

#[test]
fn discounted_gives_its_carrier_back() {
    let boxed: Box<dyn Carrier> = Box::new(Dash::new("Dash", 100, 50));
    let address: *const dyn Carrier = boxed.as_ref();
    let cheap = Discounted::new(boxed, 25).unwrap();
    assert!(
        std::ptr::eq(cheap.name(), cheap.inner().name()),
        "the name of a discounted carrier is the name of the carrier inside, not a copy"
    );
    assert_eq!(cheap.price(&small(), Zone::Local), Some(150));
    let back: Box<dyn Carrier> = cheap.into_inner();
    assert!(
        std::ptr::addr_eq(address, back.as_ref() as *const dyn Carrier),
        "into_inner must return the carrier that was put in, not a new one"
    );
}

// ---------------------------------------------------------------- dispatch

#[test]
fn cheapest_asks_each_carrier_for_one_price() {
    let counters = [
        Rc::new(Cell::new(0)),
        Rc::new(Cell::new(0)),
        Rc::new(Cell::new(0)),
    ];
    let prices = [Some(700), None, Some(650)];
    let carriers: Vec<Box<dyn Carrier>> = counters
        .iter()
        .zip(prices)
        .map(|(count, cents)| {
            Box::new(Plain {
                cents,
                prices: Rc::clone(count),
            }) as Box<dyn Carrier>
        })
        .collect();
    let quote = cheapest(&carriers, &small(), Zone::Local).unwrap();
    assert_eq!(quote.cents, 650);
    for (index, count) in counters.iter().enumerate() {
        assert_eq!(
            count.get(),
            1,
            "carrier {index} computed its price {} times during one `cheapest`; once is enough. \
             The default `accepts` computes a price too, so `accepts` followed by `price` is \
             two computations.",
            count.get()
        );
    }
}

#[test]
fn a_box_forwards_every_method() {
    let counter = Box::new(Counter::charging(500));
    assert!(ask(&counter));
    assert_eq!(
        (counter.accepts.get(), counter.prices.get()),
        (1, 0),
        "`accepts` on a Box<C> must run the carrier's own `accepts`. The carrier in this test \
         overrides it; the default body would compute a price instead."
    );

    let erased: Box<dyn Carrier> = Box::new(Counter::default());
    assert!(!ask(&erased), "this carrier declines everything");
    assert_eq!(erased.name(), "Counter");
    assert_eq!(erased.price(&small(), Zone::Local), None);
}

#[test]
fn a_discount_forwards_accepts() {
    let cheap = Discounted::new(Counter::charging(500), 10).unwrap();
    assert!(ask(&cheap));
    assert!(cheap.accepts(&small(), NEAR));
    assert_eq!(
        (cheap.inner().accepts.get(), cheap.inner().prices.get()),
        (2, 0),
        "a discount does not change whether a carrier accepts a parcel, so `accepts` of a \
         Discounted must ask the carrier inside, not compute a price"
    );
    assert_eq!(cheap.price(&small(), Zone::Local), Some(450));
    assert_eq!(cheap.inner().prices.get(), 1);
}

#[test]
fn wrappers_work_through_dynamic_dispatch() {
    // A discount on a carrier whose type is not known at compile time.
    let unknown: Box<dyn Carrier> = Box::new(Dash::new("Dash", 100, 50));
    let cheap: Discounted<Box<dyn Carrier>> = Discounted::new(unknown, 50).unwrap();
    assert_eq!(cheap.price(&small(), Zone::Local), Some(100));
    // And the discounted carrier in a list of carriers again.
    let carriers: Vec<Box<dyn Carrier>> = vec![Box::new(Snail), Box::new(cheap)];
    let quote = cheapest(&carriers, &small(), Zone::Local).unwrap();
    assert_eq!((quote.carrier.name(), quote.cents), ("Dash", 100));
    assert_eq!(total(quote.carrier, &[small(), small()], NEAR), Some(1000));
}
